    public int Fill(ChunkedResponse src) { Go(src, false, false, out _, out _); return 0; }
    public void Encode(ChunkedResponse src, out byte* p, out int len) { int rc = Go(src, false, true, out p, out len); if (rc < 0) throw new InvalidOperationException($"core encode failed: {rc}"); }
    public void EncodeU(ChunkedResponse src, out byte* p, out int len) { int rc = Go(src, true, true, out p, out len); if (rc < 0) throw new InvalidOperationException($"core encode failed: {rc}"); }
    public int TryEncode(ChunkedResponse src, bool retain, out byte* p, out int len) => Go(src, retain, true, out p, out len);
    public byte[] EncodeToArray(ChunkedResponse src, bool retain = false)
    {
        int rc = Go(src, retain, true, out byte* p, out int len);
        if (rc < 0) throw new InvalidOperationException($"core encode failed: {rc}");
        var a = new byte[len];
        new ReadOnlySpan<byte>(p, len).CopyTo(a);
        return a;
    }

    private int Go(ChunkedResponse src, bool retain, bool call, out byte* outPtr, out int outLen)
    {
        outPtr = null; outLen = 0;
        Abi.ak_enc_reset(_ctx);
        _st.Reset();
        _run->Chunk = Chunk;
        _run->Retain = retain ? 1 : 0;
        {
            var lst = src.Items;
            int n = lst == null ? 0 : lst.Count;
            _run->N_items = n;
            Arr.Ensure(ref _run->S_items, ref _cap_items, n, Math.Max(sizeof(ak_efix_ChunkElement), sizeof(ak_ufix_ChunkElement)));
            for (int i = 0; i < n; i++)
            {
                if (retain) G.U_ChunkElement(ref ((ak_ufix_ChunkElement*)_run->S_items)[i], lst[i], _st);
                else G.E_ChunkElement(ref ((ak_efix_ChunkElement*)_run->S_items)[i], lst[i], _st);
            }
            {
                int tot = 0;
                for (int i = 0; i < n; i++) { var il = lst[i].Labels; tot += il == null ? 0 : il.Count; }
                Arr.Ensure(ref _run->I_items_labels, ref _cap_items_labels, tot, sizeof(ak_str));
                { void* po = _run->O_items_labels; int c0 = _capo_items_labels; Arr.Ensure(ref po, ref c0, n, sizeof(int)); _run->O_items_labels = (int*)po;
                  void* pc = _run->C_items_labels; int c1 = _capo_items_labels; Arr.Ensure(ref pc, ref c1, n, sizeof(int)); _run->C_items_labels = (int*)pc; _capo_items_labels = c1; }
                int bi = 0;
                for (int i = 0; i < n; i++)
                {
                    var il = lst[i].Labels;
                    int m2 = il == null ? 0 : il.Count;
                    _run->O_items_labels[i] = bi; _run->C_items_labels[i] = m2;
                    for (int j = 0; j < m2; j++, bi++)
                    {
                        ((ak_str*)_run->I_items_labels)[bi] = _st.Str(il[j]);
                    }
                }
            }
            {
                int tot = 0;
                for (int i = 0; i < n; i++) { var il = lst[i].Attrs; tot += il == null ? 0 : il.Count; }
                Arr.Ensure(ref _run->I_items_attrs, ref _cap_items_attrs, tot, sizeof(ak_efix_ChunkElementAttrsEntry));
                { void* po = _run->O_items_attrs; int c0 = _capo_items_attrs; Arr.Ensure(ref po, ref c0, n, sizeof(int)); _run->O_items_attrs = (int*)po;
                  void* pc = _run->C_items_attrs; int c1 = _capo_items_attrs; Arr.Ensure(ref pc, ref c1, n, sizeof(int)); _run->C_items_attrs = (int*)pc; _capo_items_attrs = c1; }
                int bi = 0;
                for (int i = 0; i < n; i++)
                {
                    var il = lst[i].Attrs;
                    int m2 = il == null ? 0 : il.Count;
                    _run->O_items_attrs[i] = bi; _run->C_items_attrs[i] = m2;
                    for (int j = 0; j < m2; j++) { var kv = il.At(j); { ref var e = ref ((ak_efix_ChunkElementAttrsEntry*)_run->I_items_attrs)[bi]; e = default; e.key = _st.Str(kv.Key); e.value = _st.Str(kv.Value); } bi++; }
                }
            }
            {
                int tot = 0;
                for (int i = 0; i < n; i++) { var il = lst[i].Inner?.Marks; tot += il == null ? 0 : il.Count; }
                Arr.Ensure(ref _run->I_items_inner_marks, ref _cap_items_inner_marks, tot, sizeof(long));
                { void* po = _run->O_items_inner_marks; int c0 = _capo_items_inner_marks; Arr.Ensure(ref po, ref c0, n, sizeof(int)); _run->O_items_inner_marks = (int*)po;
                  void* pc = _run->C_items_inner_marks; int c1 = _capo_items_inner_marks; Arr.Ensure(ref pc, ref c1, n, sizeof(int)); _run->C_items_inner_marks = (int*)pc; _capo_items_inner_marks = c1; }
                int bi = 0;
                for (int i = 0; i < n; i++)
                {
                    var il = lst[i].Inner?.Marks;
                    int m2 = il == null ? 0 : il.Count;
                    _run->O_items_inner_marks[i] = bi; _run->C_items_inner_marks[i] = m2;
                    for (int j = 0; j < m2; j++, bi++)
                    {
                        ((long*)_run->I_items_inner_marks)[bi] = il[j];
                    }
                }
            }
            {
                int tot = 0;
                for (int i = 0; i < n; i++) { var il = lst[i].Inner?.Leaves; tot += il == null ? 0 : il.Count; }
                Arr.Ensure(ref _run->I_items_inner_leaves, ref _cap_items_inner_leaves, tot, sizeof(ak_efix_ChunkLeaf));
                { void* po = _run->O_items_inner_leaves; int c0 = _capo_items_inner_leaves; Arr.Ensure(ref po, ref c0, n, sizeof(int)); _run->O_items_inner_leaves = (int*)po;
                  void* pc = _run->C_items_inner_leaves; int c1 = _capo_items_inner_leaves; Arr.Ensure(ref pc, ref c1, n, sizeof(int)); _run->C_items_inner_leaves = (int*)pc; _capo_items_inner_leaves = c1; }
                int bi = 0;
                for (int i = 0; i < n; i++)
                {
                    var il = lst[i].Inner?.Leaves;
                    int m2 = il == null ? 0 : il.Count;
                    _run->O_items_inner_leaves[i] = bi; _run->C_items_inner_leaves[i] = m2;
                    for (int j = 0; j < m2; j++, bi++)
                    {
                        G.E_ChunkLeaf(ref ((ak_efix_ChunkLeaf*)_run->I_items_inner_leaves)[bi], il[j], _st);
                    }
                }
            }
        }
        var vt = new ak_evt_ChunkedResponse
        {
            loop_items = &Loop_items,
            elem_items = _evt_items,
        };
        nint rc;
        if (retain)
        {
            var fix = new ak_ufix_ChunkedResponse();
            G.U_ChunkedResponse(ref fix, src, _st);
            if (!call) return 0;
            _fwd++;
            rc = Abi.ak_uencode_ChunkedResponse(_run, _ctx, &vt, &fix);
        }
        else
        {
            var fix = new ak_efix_ChunkedResponse();
            G.E_ChunkedResponse(ref fix, src, _st);
            if (!call) return 0;
            _fwd++;
            rc = Abi.ak_encode_ChunkedResponse(_run, _ctx, &vt, &fix);
        }
        if (rc < 0) return (int)rc;
        byte* bp; nuint blen;
        int tk = Abi.ak_enc_take(_ctx, &bp, &blen);
        if (tk != 0) return tk;
        outPtr = bp; outLen = (int)blen;
        return 0;
    }

    [StructLayout(LayoutKind.Sequential)]
    private struct DecRun { public IntPtr Target; public byte* Buf; public IntPtr Pending; }

    private static ChunkedResponse Tgt(void* obj) => (ChunkedResponse)GCHandle.FromIntPtr(((DecRun*)obj)->Target).Target;

    [UnmanagedCallersOnly(CallConvs = new[] { typeof(CallConvCdecl) })]
    private static void ApplyRoot(IntPtr ctx, void* obj, ak_dfix_ChunkedResponse* fix)
    {
        _rev++;
        try { G.D_ChunkedResponse(ref *fix, Tgt(obj), ((DecRun*)obj)->Buf); }
        catch { Abi.ak_fail(ctx, Abi.AK_ERR_HOST, null, 0); }
    }

    [UnmanagedCallersOnly(CallConvs = new[] { typeof(CallConvCdecl) })]
    private static long New_items(IntPtr ctx, void* obj)
    {
        _rev++;
        try { var lst = Tgt(obj).Items; lst.Add(new ChunkElement()); return lst.Count - 1; }
        catch { Abi.ak_fail(ctx, Abi.AK_ERR_HOST, null, 0); return -1; }
    }

    [UnmanagedCallersOnly(CallConvs = new[] { typeof(CallConvCdecl) })]
    private static void Apply_items(IntPtr ctx, void* obj, long token, ak_dfix_ChunkElement* fix)
    {
        _rev++;
        try { var lst = Tgt(obj).Items; G.D_ChunkElement(ref *fix, lst[(int)token], ((DecRun*)obj)->Buf); }
        catch { Abi.ak_fail(ctx, Abi.AK_ERR_HOST, null, 0); }
    }

    [UnmanagedCallersOnly(CallConvs = new[] { typeof(CallConvCdecl) })]
    private static void Add_items_labels(IntPtr ctx, void* obj, long token, ak_span* xs, int n)
    {
        _rev++;
        try
        {
            byte* b = ((DecRun*)obj)->Buf;
            var e = Tgt(obj).Items[(int)token];
            var il = e.Labels;
            for (int k = 0; k < n; k++) il.Add(G.Str(b, xs[k]));
        }
        catch { Abi.ak_fail(ctx, Abi.AK_ERR_HOST, null, 0); }
    }

    [UnmanagedCallersOnly(CallConvs = new[] { typeof(CallConvCdecl) })]
    private static void Add_items_attrs(IntPtr ctx, void* obj, long token, ak_dfix_ChunkElementAttrsEntry* xs, int n)
    {
        _rev++;
        try
        {
            byte* b = ((DecRun*)obj)->Buf;
            var e = Tgt(obj).Items[(int)token];
            var il = e.Attrs;
            // plan: a duplicate key replaces the earlier value.
            for (int k = 0; k < n; k++) il[G.Str(b, xs[k].key)] = G.Str(b, xs[k].value);
        }
        catch { Abi.ak_fail(ctx, Abi.AK_ERR_HOST, null, 0); }
    }

    [UnmanagedCallersOnly(CallConvs = new[] { typeof(CallConvCdecl) })]
    private static void Add_items_inner_marks(IntPtr ctx, void* obj, long token, long* xs, int n)
    {
        _rev++;
        try
        {
            byte* b = ((DecRun*)obj)->Buf;
            var e = Tgt(obj).Items[(int)token];
            var il = (e.Inner ??= new ChunkInner()).Marks;
            for (int k = 0; k < n; k++) il.Add(xs[k]);
        }
        catch { Abi.ak_fail(ctx, Abi.AK_ERR_HOST, null, 0); }
    }

    [UnmanagedCallersOnly(CallConvs = new[] { typeof(CallConvCdecl) })]
    private static void Add_items_inner_leaves(IntPtr ctx, void* obj, long token, ak_dfix_ChunkLeaf* xs, int n)
    {
        _rev++;
        try
        {
            byte* b = ((DecRun*)obj)->Buf;
            var e = Tgt(obj).Items[(int)token];
            var il = (e.Inner ??= new ChunkInner()).Leaves;
            for (int k = 0; k < n; k++) { var x = new ChunkLeaf(); G.D_ChunkLeaf(ref xs[k], x, b); il.Add(x); }
        }
        catch { Abi.ak_fail(ctx, Abi.AK_ERR_HOST, null, 0); }
    }

    private static readonly byte[] One = new byte[1];

    public ChunkedResponse Decode(byte[] src, int len) { int rc = TryDecode(src, len, false, out var t); if (rc < 0) throw new InvalidOperationException($"core decode failed: {rc}"); return t; }
    public ChunkedResponse DecodeU(byte[] src, int len) { int rc = TryDecode(src, len, true, out var t); if (rc < 0) throw new InvalidOperationException($"core decode failed: {rc}"); return t; }

    /// The core's code (< 0) on failure; the output is then unspecified and discarded (R-G6).
    public int TryDecode(byte[] src, int len, bool retain, out ChunkedResponse result)
    {
        result = null;
        if (_dctx == IntPtr.Zero)
        {
            _dctx = Abi.ak_dec_ctx_new();
            _drun = (DecRun*)NativeMemory.AllocZeroed((nuint)sizeof(DecRun));
        }
        Abi.ak_dec_err_reset(_dctx);
        var target = new ChunkedResponse();
        var pend = retain ? new List<(int, long, byte[])>() : null;
        var h = GCHandle.Alloc(target);
        var hp = retain ? GCHandle.Alloc(pend) : default;
        int rc;
        try
        {
            fixed (byte* b0 = src)
            fixed (byte* one = One)
            {
                // (NULL, 0) is never handed to the core: an empty buffer is a valid pointer and 0.
                byte* b = len == 0 ? one : b0;
                _drun->Target = GCHandle.ToIntPtr(h);
                _drun->Buf = b;
                _drun->Pending = retain ? GCHandle.ToIntPtr(hp) : IntPtr.Zero;
                var vt = new ak_dvt_ChunkedResponse
                {
                    apply = &ApplyRoot,
                    new_items = &New_items,
                    apply_items = &Apply_items,
                    add_items_labels = &Add_items_labels,
                    add_items_attrs = &Add_items_attrs,
                    add_items_inner_marks = &Add_items_inner_marks,
                    add_items_inner_leaves = &Add_items_inner_leaves,
                };
                _fwd++;
                rc = Abi.ak_decode_ChunkedResponse(_dctx, _drun, b, (nuint)len, &vt);
                if (rc >= 0) { int he = Abi.ak_dec_err(_dctx); if (he != 0) rc = he; }
            }
        }
        finally { h.Free(); if (retain) hp.Free(); }
        if (rc < 0) return rc;
        if (retain)
        {
            // Applied after the decode: a capture may flush before the run that
            // carries the element it belongs to.
            foreach (var (slot, token, bytes) in pend)
            {
                switch (slot)
                {
                    case 0: target.UnknownFields = W.Append(target.UnknownFields, bytes, 0, bytes.Length); break;
                    case 1: { var l = target.Items; if (l != null && token >= 0 && token < l.Count) { var e = l[(int)token]; e.UnknownFields = W.Append(e.UnknownFields, bytes, 0, bytes.Length); } break; }
                    default: break;   // a map entry has no bag
                }
            }
        }
        result = target;
        return 0;
    }

    /// ABI v1 7.1's PULL family: parse into the context's record stream (no reverse
    /// call), then replay it with the same group readers the push callbacks use.
    public ChunkedResponse Pull(byte[] src, int len)
    {
        if (_dctx == IntPtr.Zero)
        {
            _dctx = Abi.ak_dec_ctx_new();
            _drun = (DecRun*)NativeMemory.AllocZeroed((nuint)sizeof(DecRun));
        }
        var t = new ChunkedResponse();
        fixed (byte* b0 = src)
        fixed (byte* one = One)
        {
            byte* b = len == 0 ? one : b0;
            _fwd++;
            int rc = Abi.ak_parse_ChunkedResponse(_dctx, b, (nuint)len);
            if (rc < 0) throw new InvalidOperationException($"core parse failed: {rc}");
            byte* recs; nuint rlen;
            _fwd++;
            int pr = Abi.ak_bdr_ptr(_dctx, &recs, &rlen);
            if (pr != 0) throw new InvalidOperationException($"ak_bdr_ptr failed: {pr}");
            Replay(t, b, recs, (int)rlen);
        }
        return t;
    }

    private const uint OP_APPLY = 1, OP_ADD = 2, OP_NEW = 3, OP_APPLY_ELEM = 4;   // ak_bdr_rec.op
    private static void Replay(ChunkedResponse t, byte* b, byte* p, int len)
    {
        int at = 0;
        while (len - at >= sizeof(ak_bdr_rec))
        {
            ref var r = ref *(ak_bdr_rec*)(p + at);
            byte* body = p + at + sizeof(ak_bdr_rec);
            at += sizeof(ak_bdr_rec) + (int)r.bytes;
            uint outer = r.slot >> 16, inner = r.slot & 0xFFFF;
            switch (r.op)
            {
                case OP_APPLY: G.D_ChunkedResponse(ref *(ak_dfix_ChunkedResponse*)body, t, b); break;
                case OP_NEW when outer == 1: t.Items.Add(new ChunkElement()); break;
                case OP_APPLY_ELEM when outer == 1: G.D_ChunkElement(ref *(ak_dfix_ChunkElement*)body, t.Items[(int)r.token], b); break;
                case OP_ADD when outer == 1 && inner == 1:
                {
                    var xs = (ak_span*)body; var e = t.Items[(int)r.token]; var il = e.Labels;
                    for (int k = 0; k < (int)r.n; k++) il.Add(G.Str(b, xs[k]));
                    break;
                }
                case OP_ADD when outer == 1 && inner == 2:
                {
                    var xs = (ak_dfix_ChunkElementAttrsEntry*)body; var e = t.Items[(int)r.token]; var il = e.Attrs;
                    // plan: a duplicate key replaces the earlier value.
                    for (int k = 0; k < (int)r.n; k++) il[G.Str(b, xs[k].key)] = G.Str(b, xs[k].value);
                    break;
                }
                case OP_ADD when outer == 1 && inner == 3:
                {
                    var xs = (long*)body; var e = t.Items[(int)r.token]; var il = (e.Inner ??= new ChunkInner()).Marks;
                    for (int k = 0; k < (int)r.n; k++) il.Add(xs[k]);
                    break;
                }
                case OP_ADD when outer == 1 && inner == 4:
                {
                    var xs = (ak_dfix_ChunkLeaf*)body; var e = t.Items[(int)r.token]; var il = (e.Inner ??= new ChunkInner()).Leaves;
                    for (int k = 0; k < (int)r.n; k++) { var x = new ChunkLeaf(); G.D_ChunkLeaf(ref xs[k], x, b); il.Add(x); }
                    break;
                }
                default: break;
            }
        }
    }

    public long PullFootprint() => _dctx == IntPtr.Zero ? 0 : (long)Abi.ak_bdr_footprint(_dctx);
    public AkCounters EncCounters() { AkCounters c; Abi.ak_enc_counters(_ctx, &c); return c; }
    public void EncCountersReset() => Abi.ak_enc_counters_reset(_ctx);
    public AkCounters DecCounters() { AkCounters c; if (_dctx == IntPtr.Zero) return default; Abi.ak_dec_counters(_dctx, &c); return c; }
    public void DecCountersReset() { if (_dctx != IntPtr.Zero) Abi.ak_dec_counters_reset(_dctx); }

    public void Dispose()
    {
        if (_ctx != IntPtr.Zero) { Abi.ak_enc_ctx_free(_ctx); _ctx = IntPtr.Zero; }
        if (_dctx != IntPtr.Zero) { Abi.ak_dec_ctx_free(_dctx); _dctx = IntPtr.Zero; }
        _st.Dispose();
        if (_run != null)
        {
            NativeMemory.Free(_run->S_items);
            NativeMemory.Free(_run->I_items_labels); NativeMemory.Free(_run->O_items_labels); NativeMemory.Free(_run->C_items_labels);
            NativeMemory.Free(_run->I_items_attrs); NativeMemory.Free(_run->O_items_attrs); NativeMemory.Free(_run->C_items_attrs);
            NativeMemory.Free(_run->I_items_inner_marks); NativeMemory.Free(_run->O_items_inner_marks); NativeMemory.Free(_run->C_items_inner_marks);
            NativeMemory.Free(_run->I_items_inner_leaves); NativeMemory.Free(_run->O_items_inner_leaves); NativeMemory.Free(_run->C_items_inner_leaves);
            NativeMemory.Free(_run); _run = null;
        }
        if (_evt_items != null) { NativeMemory.Free(_evt_items); _evt_items = null; }
        if (_drun != null) { NativeMemory.Free(_drun); _drun = null; }
    }
}

[StructLayout(LayoutKind.Sequential)]
public unsafe struct Run_ChunkedResponseWide
